UPDATE rag_knowledge_base 
SET quality_score = GREATEST(quality_score - #{degradation}, 0),
    usage_count = usage_count + 1
WHERE sql_example LIKE #{tableNamePattern}
   OR question LIKE #{keywordsPattern}

UPDATE rag_feedback 
SET feedback_text = CONCAT(IFNULL(feedback_text, ''), '|ERROR_CATEGORIES:', #{categoriesStr})
WHERE id = #{feedbackId}
